-- 1103: Codex soru kalite taraması (11.185 karar + 5 tekrar eşleşmesi) + bekleyen İngilizce paketi (303).
-- Soru SİLİNMEZ, metne dokunulmaz, zorluk_oneri uygulanmaz. Kaynak: araclar/soru-uretim/denetim/karar (git dışı),
-- üretici uret-1103.cjs. Geri alma: docs/soru-tarama-1103-geri-al.sql.
--  cikar  → aktif=false, denetim_durumu='reddedildi', soru_denetim.sebep = tekrar | dogruluk | diger
--  duzelt → aktif kalır, denetim_durumu 'bekliyor' kalır (şüpheli işaretli soru rekabetçi havuz dışında kalır),
--           soru_denetim.sebep = duzelt_sik | duzelt_diger; kategori_dogru farklıysa kategori düzeltilir
--  tut    → denetim_durumu='onaylandi' (soru_denetim_ice_aktar › onayla ile aynı)
--  en_durum=cikar → EN çeviri eskidi=true (o dilde sorulmaz) + ceviri_atlanan kod 'denetim_1103'
--  EN paketi → question_translations (en), ceviri_atlanan satırı kalkar

create temp table _k1103 (id uuid primary key, karar text not null, sebep text not null,
  kategori text not null, en_cikar boolean not null, notu text) on commit drop;

create temp table _e1103 (id uuid primary key, soru text not null, secenekler jsonb not null) on commit drop;

do $$
declare v_n int;
begin
  -- Tekrar güvencesi: bir tekrar çiftinde tutulan kayıt da pasife düşmesin
  select count(*) into v_n from _k1103 k
   where k.sebep = 'tekrar'
     and not exists (
       select 1 from regexp_matches(k.notu, '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', 'g') m(x)
         join public.questions q2 on q2.id = m.x[1]::uuid
        where q2.aktif and q2.id <> k.id
          and not exists (select 1 from _k1103 k2 where k2.id = q2.id and k2.karar = 'cikar'));
  if v_n > 0 then raise exception '1103: % tekrar kaydının tutulan eşi aktif kalmıyor', v_n; end if;
end $$;

-- 1) çıkar → pasif
update public.questions q set aktif = false, denetim_durumu = 'reddedildi'
  from _k1103 k where k.id = q.id and k.karar = 'cikar';

-- 2–3) düzelt → yalnız işaret; kategori düzeltmesi
update public.questions q set kategori = k.kategori
  from _k1103 k where k.id = q.id and k.kategori is distinct from q.kategori;

-- 4) tut → onay
update public.questions q set denetim_durumu = 'onaylandi'
  from _k1103 k where k.id = q.id and k.karar = 'tut' and q.denetim_durumu = 'bekliyor';

select k.id,
       case k.karar when 'cikar' then 'reddedildi' when 'tut' then 'onaylandi' else 'bekliyor' end,
       k.sebep, 'codex_tarama_1103', 'codex', k.notu
  from _k1103 k;

-- 5) EN çıkar → çeviri eskidi + atlanan
update public.question_translations t set eskidi = true, eskidi_at = now()
  from _k1103 k where k.id = t.question_id and t.dil = 'en' and k.en_cikar and not t.eskidi;
select k.id, 'en', 'Denetim 1103: İngilizce oyuncu için uygun değil', 'denetim_1103'
  from _k1103 k where k.en_cikar
on conflict (question_id, dil) do nothing;

-- 6) EN paketi
select e.id, 'en', e.soru, e.secenekler from _e1103 e;
delete from public.ceviri_atlanan a using _e1103 e where a.question_id = e.id and a.dil = 'en';

select public.kategori_havuz_yenile();
